import express from 'express';
import cors from 'cors';
import helmet from 'helmet';
import dotenv from 'dotenv';
import { DatabaseService } from './services/database';
import { healthRouter } from './routes/health';
import { apiRouter } from './routes/api';

// Load environment variables
dotenv.config();

// Initialize services
const db = new DatabaseService(process.env.DB_PATH || './data/database.sqlite');

// Create Express app
const app = express();

// Middleware
app.use(helmet());
app.use(cors());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Routes
app.use('/health', healthRouter);
app.use('/api', apiRouter);

// Root endpoint
app.get('/', (req, res) => {
  res.json({
    name: 'Node Express SQLite PM2 Example',
    version: '1.0.0',
    endpoints: {
      health: '/health',
      api: '/api'
    }
  });
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Error handler
app.use((err: Error, req: express.Request, res: express.Response, next: express.NextFunction) => {
  console.error(err);
  res.status(500).json({
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'Something went wrong'
  });
});

export { app, db };

import { Express } from 'express';
import { createServer } from 'http';
import { app, db } from './index';

const PORT = parseInt(process.env.PORT || '3000', 10);

async function startServer() {
  try {
    // Initialize database
    await db.init();
    console.log('✅ Database initialized');

    // Create HTTP server
    const server = createServer(app);

    // Start server
    server.listen(PORT, () => {
      console.log(`✅ Server is running on http://localhost:${PORT}`);
      console.log(`📊 Health check: http://localhost:${PORT}/health`);
      console.log(`📚 API docs: http://localhost:${PORT}/api`);
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      console.log('🛑 Graceful shutdown...');
      server.close(() => {
        console.log('✅ Server closed');
        db.close();
        process.exit(0);
      });
    });

    process.on('SIGINT', () => {
      console.log('🛑 Graceful shutdown...');
      server.close(() => {
        console.log('✅ Server closed');
        db.close();
        process.exit(0);
      });
    });
  } catch (error) {
    console.error('❌ Failed to start server:', error);
    process.exit(1);
  }
}

startServer();

import Database from 'better-sqlite3';
import { logger } from '../utils/logger';

export class DatabaseService {
  private db: Database.Database | null = null;
  private dbPath: string;

  constructor(dbPath: string = './data/database.sqlite') {
    this.dbPath = dbPath;
  }

  async init(): Promise<void> {
    try {
      // Create database connection
      this.db = new Database(this.dbPath);

      // Enable foreign keys
      this.db.pragma('foreign_keys = ON');

      // Create tables
      await this.createTables();

      logger.info('Database initialized successfully');
    } catch (error) {
      logger.error('Failed to initialize database:', error);
      throw error;
    }
  }

  private async createTables(): Promise<void> {
    if (!this.db) throw new Error('Database not initialized');

    const createUsersTable = `
      CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        email TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user' CHECK(role IN ('user', 'admin')),
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
      )
    `;

    const createPostsTable = `
      CREATE TABLE IF NOT EXISTS posts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        content TEXT,
        user_id INTEGER NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (user_id) REFERENCES users(id)
      )
    `;

    const createIndexes = `
      CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);
      CREATE INDEX IF NOT EXISTS idx_posts_user_id ON posts(user_id);
    `;

    this.db.exec(createUsersTable);
    this.db.exec(createPostsTable);
    this.db.exec(createIndexes);
  }

  getDb(): Database.Database {
    if (!this.db) {
      throw new Error('Database not initialized. Call init() first.');
    }
    return this.db;
  }

  close(): void {
    if (this.db) {
      this.db.close();
      this.db = null;
      logger.info('Database connection closed');
    }
  }
}

import { Router } from 'express';

const router = Router();

/**
 * @route GET /health
 * @description Health check endpoint with database status
 */
router.get('/', (req, res) => {
  const healthStatus = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    environment: process.env.NODE_ENV || 'development'
  };

  res.status(200).json(healthStatus);
});

/**
 * @route GET /health/database
 * @description Check database connectivity
 */
router.get('/database', async (req, res) => {
  try {
    const { db } = await import('../index');
    const dbInstance = db.getDb();

    // Simple query to test connection
    const result = dbInstance.prepare('SELECT 1 as test').get();

    res.status(200).json({
      status: 'healthy',
      database: 'connected',
      test: result
    });
  } catch (error) {
    res.status(503).json({
      status: 'unhealthy',
      database: 'disconnected',
      error: error instanceof Error ? error.message : 'Unknown error'
    });
  }
});

export { router as healthRouter };

import { Router, Request, Response } from 'express';

const router = Router();

/**
 * @route GET /api
 * @description API root endpoint
 */
router.get('/', (req: Request, res: Response) => {
  res.json({
    version: '1.0.0',
    endpoints: {
      users: '/users',
      posts: '/posts'
    }
  });
});

/**
 * @route GET /api/users
 * @description Get all users
 */
router.get('/users', (req: Request, res: Response) => {
  res.json({
    message: 'Users endpoint',
    users: []
  });
});

/**
 * @route GET /api/users/:id
 * @description Get user by ID
 */
router.get('/users/:id', (req: Request, res: Response) => {
  const { id } = req.params;
  res.json({
    message: `User ${id}`,
    user: { id, name: 'Example User' }
  });
});

/**
 * @route GET /api/posts
 * @description Get all posts
 */
router.get('/posts', (req: Request, res: Response) => {
  res.json({
    message: 'Posts endpoint',
    posts: []
  });
});

export { router as apiRouter };

import winston from 'winston';

const logLevel = process.env.LOG_LEVEL || 'info';

const logger = winston.createLogger({
  level: logLevel,
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  transports: [
    // Console transport
    new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.simple()
      )
    })
  ]
});

